n=16
six={(0,8),(1,7),(2,6),(2,10),(3,5),(3,9),(4,4),(4,8),(5,3),(5,7),(6,2),(6,6),(6,11),(7,1),(7,5),(7,10),(8,0),(8,4),(8,9),(9,3),(9,8),(10,2),(10,7),(10,12),(11,6),(11,11)}
# rectangles between line pairs with overlapped v extents
lines={8:(-8,8),12:(-8,8),17:(-5,5),22:(-2,0)}
out=[[8]*16 for _ in range(16)]
for r,c in six: out[r][c]=6
for ua,ub in [(8,12),(12,17),(17,22)]:
    vlo=max(lines[ua][0],lines[ub][0]); vhi=min(lines[ua][1],lines[ub][1])
    for r in range(16):
        for c in range(16):
            u=r+c; v=r-c
            if ua<u<ub and vlo<=v<=vhi and (r,c) not in six:
                out[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in out))
